import json

def get_near_105k(path):
    target = 105000
    # Collect entries with eval_return and value_mean
    candidates = []
    with open(path) as f:
        for line in f:
            d = json.loads(line)
            if 'eval_return' in d and 'value_mean' in d:
                candidates.append(d)
    # Find closest to 105K
    if not candidates:
        # Try separate: eval_return and value_mean might be on different lines
        eval_entries = []
        value_entries = []
        with open(path) as f:
            for line in f:
                d = json.loads(line)
                if 'eval_return' in d:
                    eval_entries.append(d)
                if 'value_mean' in d:
                    value_entries.append(d)
        # Find closest eval and value to 105K
        eval_best = min(eval_entries, key=lambda x: abs(x['step'] - target))
        value_best = min(value_entries, key=lambda x: abs(x['step'] - target))
        return {'eval_step': eval_best['step'], 'eval_return': eval_best['eval_return'],
                'value_step': value_best['step'], 'value_mean': value_best['value_mean']}
    best = min(candidates, key=lambda x: abs(x['step'] - target))
    return {'step': best['step'], 'eval_return': best['eval_return'], 'value_mean': best['value_mean']}

paths = {
    '023a': '/root/autodl-tmp/event-gated-adaptive-horizon/logdir/exp_023a_cheetah_baseline_s0/metrics.jsonl',
    '023b': '/root/autodl-tmp/event-gated-adaptive-horizon/logdir/exp_023b_cheetah_baseline_s1/metrics.jsonl',
    '010b': '/root/autodl-tmp/event-gated-adaptive-horizon/logdir/exp_010b_cheetah_civo_trigger/metrics.jsonl',
}

for name, path in paths.items():
    result = get_near_105k(path)
    print(f'{name}: {json.dumps(result)}')
